GRADLEW = r"""#!/bin/sh
set -eu
if command -v gradle >/dev/null 2>&1; then
    exec gradle "$@"
fi
echo "Gradle 8.7 is required. Install it or open this project in Android Studio."
exit 1
"""

GRADLEW_BAT = r"""@echo off
where gradle >nul 2>nul
if %ERRORLEVEL% EQU 0 (
    gradle %*
    exit /b %ERRORLEVEL%
)
echo Gradle 8.7 is required. Install it or open this project in Android Studio.
exit /b 1
"""

def main():
    if ROOT.exists():
        shutil.rmtree(ROOT)
    if ZIP_NAME.exists():
        ZIP_NAME.unlink()

    for rel, content in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")

    (ROOT / "gradlew").write_text(GRADLEW, encoding="utf-8")
    (ROOT / "gradlew").chmod(0o755)
    (ROOT / "gradlew.bat").write_text(GRADLEW_BAT, encoding="utf-8")

    with zipfile.ZipFile(ZIP_NAME, "w", zipfile.ZIP_DEFLATED) as z: 
        for path in ROOT.rglob("*"):
            if path.is_file():
                z.write(path, path.relative_to(ROOT))

    print(f"Project created: {ROOT.resolve()}")
    print(f"ZIP created:     {ZIP_NAME.resolve()}")

if __name__ == "__main__":
    main()
